-- Replaces the standard onboarding catalog of 0048 (plans/crm/18-portal-prozess-nacharbeiten/D-standardbogen-website-onboarding.md).
-- The old catalog was never used in production. Forms keep their own block copies: source_block_id and
-- source_template_id fall back to NULL through their foreign keys.
-- Templates go first because questionnaire_template_blocks restricts deleting a block that is still in use.
DELETE FROM questionnaire_templates;
--> statement-breakpoint
DELETE FROM questionnaire_blocks WHERE owner_form_id IS NULL;
