INSERT INTO questionnaire_block_translations (block_id, locale, title, intro)
VALUES ('13eab88b-2638-5f82-855a-6692f79ceea7', 'de', 'Ansprechpartner & Freigaben', 'Damit Abstimmungen schnell gehen: Wen erreichen wir, und wer entscheidet?'),
       ('13eab88b-2638-5f82-855a-6692f79ceea7', 'en', 'Contacts & approvals', 'So decisions move quickly: who can we reach, and who signs off?'),
       ('a4bb761e-bed8-59fa-9152-717eb8eb14bb', 'de', 'Vereinbarte Leistungen', 'Diese Leistungen sind Teil deines Projekts. Bitte prüfe kurz, ob alles so passt.'),
       ('a4bb761e-bed8-59fa-9152-717eb8eb14bb', 'en', 'Agreed services', 'These services are part of your project. Please check that everything is right.'),
       ('85e85857-d638-5817-aa6a-878aded5d56a', 'de', 'Unternehmen', 'Wer seid ihr, und warum kommen Kunden zu euch? Stichpunkte reichen völlig.'),
       ('85e85857-d638-5817-aa6a-878aded5d56a', 'en', 'Company', 'Who are you, and why do customers come to you? Bullet points are perfectly fine.'),
       ('69a77314-02ee-5880-a749-8172f22ee960', 'de', 'Zielgruppe', 'Je besser wir eure Kunden kennen, desto treffender werden die Texte. Stichpunkte reichen.'),
       ('69a77314-02ee-5880-a749-8172f22ee960', 'en', 'Target audience', 'The better we know your customers, the sharper the copy. Bullet points are fine.'),
       ('a5cdfc25-c129-5538-9897-6dcb28523ae2', 'de', 'Leistungen', 'Leg für jede Leistung, die auf der Website vorkommen soll, einen Eintrag an. Vollständigkeit ist wichtiger als schöne Formulierungen.'),
       ('a5cdfc25-c129-5538-9897-6dcb28523ae2', 'en', 'Services', 'Add an entry for every service that should appear on the website. Completeness matters more than polished wording.'),
       ('7aa2129a-ead3-5e9f-8984-11ee8a8c7b1c', 'de', 'Über uns', 'Menschen kaufen von Menschen. Erzähl, was euch ausmacht. Stichpunkte reichen.'),
       ('7aa2129a-ead3-5e9f-8984-11ee8a8c7b1c', 'en', 'About us', 'People buy from people. Tell us what makes you who you are. Bullet points are fine.'),
       ('7cfd79fc-9323-55ba-9973-ae34ec9f01a9', 'de', 'Team', NULL),
       ('7cfd79fc-9323-55ba-9973-ae34ec9f01a9', 'en', 'Team', NULL),
       ('266ff607-f962-5baa-b0da-9ab10b46e447', 'de', 'Kundenstimmen & Beispiele', NULL),
       ('266ff607-f962-5baa-b0da-9ab10b46e447', 'en', 'Testimonials & examples', NULL),
       ('5de40bd7-2d6e-5970-954a-e01879d69c2a', 'de', 'Vertrauen & Kennzahlen', 'Was zeigt auf einen Blick, dass man euch vertrauen kann?'),
       ('5de40bd7-2d6e-5970-954a-e01879d69c2a', 'en', 'Trust & key figures', 'What shows at a glance that people can trust you?'),
       ('defad24f-00e8-51e3-a00f-e33ae7d80394', 'de', 'Häufige Fragen', 'Welche Fragen hört ihr immer wieder? Stichpunkte reichen, wir formulieren aus.'),
       ('defad24f-00e8-51e3-a00f-e33ae7d80394', 'en', 'Frequently asked questions', 'Which questions do you hear again and again? Bullet points are fine, we’ll write them up.'),
       ('6352404c-d2be-5829-b094-ab554dceb59d', 'de', 'Texte & Ansprache', 'Du musst keine fertigen Texte liefern. Wir bereiten alles für die Website auf.'),
       ('6352404c-d2be-5829-b094-ab554dceb59d', 'en', 'Copy & tone of voice', 'You don’t need finished copy. We’ll shape everything for the website.'),
       ('3bca346f-7410-5c32-b3a7-3ad15ace482c', 'de', 'Logo & Brand Guide', 'Am besten als SVG, sonst PNG mit transparentem Hintergrund.'),
       ('3bca346f-7410-5c32-b3a7-3ad15ace482c', 'en', 'Logo & brand guide', 'SVG works best, otherwise PNG with a transparent background.'),
       ('c1c994b4-b424-5576-baa7-b2888f477554', 'de', 'Farben & Schriften', NULL),
       ('c1c994b4-b424-5576-baa7-b2888f477554', 'en', 'Colours & fonts', NULL),
       ('9a5b8d16-efd9-5325-b6e6-cbf9116c68cb', 'de', 'Designrichtung', 'Keine Sorge, wenn du noch keine Vorstellung hast. Dann machen wir Vorschläge.'),
       ('9a5b8d16-efd9-5325-b6e6-cbf9116c68cb', 'en', 'Design direction', 'Don’t worry if you have no clear idea yet. We’ll come up with suggestions.'),
       ('a26b81f3-8e4d-5616-a8fe-c2ad6a0555bd', 'de', 'Websites, die dir gefallen', 'Egal aus welcher Branche: Zeig uns Websites, die dir gefallen. Zwei oder drei reichen.'),
       ('a26b81f3-8e4d-5616-a8fe-c2ad6a0555bd', 'en', 'Websites you like', 'From any industry: show us websites you like. Two or three are enough.'),
       ('95879dbe-75c5-5f6c-9833-711ccb0c7438', 'de', 'Fotos, Videos & Unterlagen', 'Bitte im Original und in voller Auflösung hochladen, nicht aus WhatsApp und nicht zugeschnitten. Lieber zu viel Auswahl als zu wenig.'),
       ('95879dbe-75c5-5f6c-9833-711ccb0c7438', 'en', 'Photos, videos & documents', 'Please upload originals in full resolution, not from WhatsApp and not cropped. More choice is better than too little.'),
       ('0620a20f-8562-55c1-a16e-4c840823ba75', 'de', 'Bestehende Website', NULL),
       ('0620a20f-8562-55c1-a16e-4c840823ba75', 'en', 'Existing website', NULL),
       ('71dd7eca-4773-5ea6-b27e-fb2d790e27d4', 'de', 'Google & Suche', NULL),
       ('71dd7eca-4773-5ea6-b27e-fb2d790e27d4', 'en', 'Google & search', NULL),
       ('d341956e-804d-565b-bdc0-8171fd6922ae', 'de', 'Domain, E-Mail & vorhandene Dienste', 'Wir brauchen hier nur Fakten, keine Passwörter. Weißt du etwas nicht, finden wir es heraus.'),
       ('d341956e-804d-565b-bdc0-8171fd6922ae', 'en', 'Domain, email & existing services', 'We only need facts here, no passwords. If you don’t know something, we’ll find out.'),
       ('1e81b498-f7d7-5670-94e7-210b1df614c8', 'de', 'Kontaktdaten & Social Media', 'Diese Angaben erscheinen öffentlich auf der Website. Trag nur ein, was dort stehen soll.'),
       ('1e81b498-f7d7-5670-94e7-210b1df614c8', 'en', 'Contact details & social media', 'These details appear publicly on the website. Only enter what should be shown there.'),
       ('2c2f6b5c-8a5f-563e-ab15-102500c07ecb', 'de', 'Impressum & Datenschutz', 'Firmenname und Anschrift übernehmen wir aus deinen Angaben oben.'),
       ('2c2f6b5c-8a5f-563e-ab15-102500c07ecb', 'en', 'Legal notice & privacy', 'We take company name and address from your details above.'),
       ('628b4b88-cf14-578f-b467-a0f7ff4ec98f', 'de', 'Abschluss', 'Fast geschafft. Noch die Bestätigung, und was dir sonst wichtig ist.'),
       ('628b4b88-cf14-578f-b467-a0f7ff4ec98f', 'en', 'Wrap-up', 'Almost done. Just the confirmation, and anything else that matters to you.')
